"""TensorRT pack for the ConvNeXt-S fast kernel (generated by cnxs_pack/make.py; see its docstring)."""
import glob, hashlib, json, os, shutil, subprocess, sys, time
P = "/kaggle/working/trtpack"; os.makedirs(P, exist_ok=True); M = {"ln": "ln32"}
t = time.perf_counter()
p = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "tensorrt-cu12==11.4.0.106", "tensorrt-lean-cu12==11.4.0.106", "onnx"],
                   capture_output=True, text=True)
M["pip_s"] = round(time.perf_counter() - t, 1); print("pip", p.returncode, p.stderr[-1500:], flush=True); assert p.returncode == 0
BUILD = r"""
import glob, json, sys, time, types
import torch, torch.nn.functional as F, tensorrt as trt
tz = glob.glob("/kaggle/input/**/timm_1.0.29_cp313_pyc.pyz", recursive=True)[0]
sys.path.insert(0, tz)
for n in ("torchvision", "torchvision.ops", "torchvision.ops.misc"):
    sys.modules[n] = types.ModuleType(n)
sys.modules["torchvision.ops.misc"].FrozenBatchNorm2d = type("FrozenBatchNorm2d", (torch.nn.Module,), {})
for n in ("timm", "timm.models", "timm.data"):
    m = types.ModuleType(n); m.__path__ = [tz + "/" + n.replace(".", "/")]; sys.modules[n] = m
sys.modules["timm"].__version__ = "1.0.29"
import timm.data.constants as tdc
vars(sys.modules["timm.data"]).update({k: v for k, v in vars(tdc).items() if k.isupper()})
from timm.models.convnext import convnext_small
from timm.layers import LayerNorm, LayerNorm2d
eng_path, mode = sys.argv[1], sys.argv[2]
dev = torch.device("cuda:0")
W0 = torch.load(glob.glob("/kaggle/input/**/cnxs_global_fp16.pt", recursive=True)[0], map_location="cpu", weights_only=True)
with torch.device(dev):
    bb = convnext_small(pretrained=False, num_classes=0)
bb.load_state_dict({k[9:]: v for k, v in W0.items() if k.startswith("backbone.")}, strict=True)
bb = bb.half().eval().to(memory_format=torch.channels_last)
g = torch.Generator(device=dev).manual_seed(0)
xs = [torch.randn(94, 3, 320, 320, device=dev, generator=g).half() for _ in range(3)]
class FF(torch.nn.Module):
    def __init__(s, m): super().__init__(); s.m = m
    def forward(s, x): return s.m.forward_head(s.m.forward_features(x))
ff = FF(bb)
with torch.inference_mode():
    ref = [ff(x.contiguous(memory_format=torch.channels_last)).float() for x in xs]
R = {"mode": mode}
def timeit(fn, n=10):
    with torch.inference_mode():
        for _ in range(3): fn(xs[0])
        torch.cuda.synchronize(); e0, e1 = torch.cuda.Event(True), torch.cuda.Event(True); e0.record()
        for i in range(n): fn(xs[i % 3])
        e1.record(); torch.cuda.synchronize(); return round(e0.elapsed_time(e1) / n, 2)
R["torch_ms"] = timeit(lambda x: torch.cat([ff(x[i:i + 48].contiguous(memory_format=torch.channels_last)) for i in (0, 48)]))
if mode == "ln32":                                   # LayerNorm math in fp32 (cast in, fp32 weights, cast out)
    def ln_fwd(s, x):
        return F.layer_norm(x.float(), s.normalized_shape, s.weight.float(), s.bias.float(), s.eps).to(x.dtype)
    def ln2d_fwd(s, x):
        x = x.permute(0, 2, 3, 1)
        x = F.layer_norm(x.float(), s.normalized_shape, s.weight.float(), s.bias.float(), s.eps).to(x.dtype)
        return x.permute(0, 3, 1, 2)
    nln = 0
    for m in bb.modules():
        if isinstance(m, LayerNorm2d):
            m.forward = types.MethodType(ln2d_fwd, m); nln += 1
        elif isinstance(m, LayerNorm):
            m.forward = types.MethodType(ln_fwd, m); nln += 1
    R["ln_patched"] = nln
t = time.perf_counter()
with torch.inference_mode():
    torch.onnx.export(ff, (xs[0].contiguous(),), f"/kaggle/working/cnxs_{mode}_{sys.argv[3]}.onnx", input_names=["x"], output_names=["f"],
                      opset_version=17, dynamo=False)
R["onnx_s"] = round(time.perf_counter() - t, 1)
L = trt.Logger(trt.Logger.WARNING); b = trt.Builder(L)
net = b.create_network(1 << int(trt.NetworkDefinitionCreationFlag.STRONGLY_TYPED)); pr = trt.OnnxParser(net, L)
assert pr.parse_from_file(f"/kaggle/working/cnxs_{mode}_{sys.argv[3]}.onnx"), [pr.get_error(i).desc() for i in range(pr.num_errors)]
c = b.create_builder_config(); c.set_memory_pool_limit(trt.MemoryPoolType.WORKSPACE, 4 << 30); c.builder_optimization_level = 4
if len(sys.argv) > 3 and sys.argv[3] == "vc":    # lean runtime: version-compatible plan, lean runtime shipped apart
    c.set_flag(trt.BuilderFlag.VERSION_COMPATIBLE); c.set_flag(trt.BuilderFlag.EXCLUDE_LEAN_RUNTIME)
t = time.perf_counter(); ser = b.build_serialized_network(net, c); R["build_s"] = round(time.perf_counter() - t, 1)
open(eng_path, "wb").write(bytes(ser)); R["engine_MB"] = round(len(bytes(ser)) / 1e6, 1)
rt = trt.Runtime(L); rt.engine_host_code_allowed = True; eng = rt.deserialize_cuda_engine(ser); ctx = eng.create_execution_context()
out = torch.empty((94, 768), dtype=torch.half, device=dev); ts = torch.cuda.Stream(dev)
def tf(x):
    x = x.contiguous(); cur = torch.cuda.current_stream(dev); ts.wait_stream(cur)
    ctx.set_tensor_address("x", x.data_ptr()); ctx.set_tensor_address("f", out.data_ptr())
    ctx.execute_async_v3(ts.cuda_stream); cur.wait_stream(ts); return out
R["trt_ms"] = timeit(tf)
with torch.inference_mode():
    d = [(tf(x).float() - r) for x, r in zip(xs, ref)]
R["feat_maxdiff"] = round(max(float(v.abs().max()) for v in d), 5); R["feat_meandiff"] = round(float(sum(v.abs().mean() for v in d) / 3), 6)
R["ref_absmean"] = round(float(ref[0].abs().mean()), 4); R["gpu"] = torch.cuda.get_device_name(0); R["trt"] = trt.__version__
print(json.dumps(R), flush=True)
"""
open("/kaggle/working/build.py", "w").write(BUILD)
for tag in ("full", "vc"):
    p = subprocess.run([sys.executable, "/kaggle/working/build.py", f"{P}/cnxs_{tag}.engine", "ln32", tag], capture_output=True, text=True)
    print(tag, p.returncode, p.stdout[-800:], p.stderr[-2500:], flush=True); assert p.returncode == 0
    M[f"build_{tag}"] = json.loads(p.stdout.strip().splitlines()[-1])
for f in glob.glob("/kaggle/working/*.onnx"):
    os.remove(f)
import site
sp = [d for d in site.getsitepackages() if os.path.isdir(os.path.join(d, "tensorrt_libs"))][0]
def cp(pkg, dst, only=None):
    src = os.path.join(sp, pkg); os.makedirs(os.path.join(P, dst, pkg), exist_ok=True)
    for f in os.listdir(src):
        if f == "__pycache__" or (only and f not in only):
            continue
        s = os.path.join(src, f); d = os.path.join(P, dst, pkg, f)
        (shutil.copytree if os.path.isdir(s) else shutil.copy2)(s, d)
M["tensorrt_libs"] = sorted(os.listdir(os.path.join(sp, "tensorrt_libs")))
cp("tensorrt", "full"); cp("tensorrt_bindings", "full")
cp("tensorrt_libs", "full", {"__init__.py", "libnvinfer.so.11", "libnvonnxparser.so.11"})
cp("tensorrt_lean", "lean"); cp("tensorrt_lean_bindings", "lean"); cp("tensorrt_lean_libs", "lean")
def sha(f):
    h = hashlib.sha256()
    with open(f, "rb") as fh:
        for b in iter(lambda: fh.read(1 << 20), b""): h.update(b)
    return h.hexdigest()
M["files"] = {os.path.relpath(f, P): [os.path.getsize(f), sha(f)] for f in sorted(glob.glob(f"{P}/**/*", recursive=True)) if os.path.isfile(f)}
import torch
M["gpu"] = torch.cuda.get_device_name(0); M["python"] = sys.version.split()[0]; M["torch"] = torch.__version__
M["total_MB"] = round(sum(v[0] for v in M["files"].values()) / 1e6, 1)
json.dump(M, open(f"{P}/manifest.json", "w"), indent=1)
print("PACK", json.dumps({k: v for k, v in M.items() if k != "files"}), flush=True)
